#!/usr/bin/env bash
# Builds a static site from the architecture documentation generated by the backend tests
# (ArchitectureTest, ArchitectureDiagramTest and JMoleculesCatalogTest).
#
# Usage: build-architecture-site.sh <output-dir> <generated-docs-dir>...
# The generated folders are merged (they have no file names in common).
# Requires: PlantUML >= 1.2025 (the Modulith diagrams use the C4 standard library, missing in older
# versions), graphviz and asciidoctor. Set PLANTUML to the command that runs PlantUML.
set -euo pipefail

out="${1:?usage: $0 <output-dir> <generated-docs-dir>...}"
sources=("${@:2}")
if [[ ${#sources[@]} -eq 0 ]]; then
  echo "usage: $0 <output-dir> <generated-docs-dir>..." >&2
  exit 1
fi

src="$(mktemp -d)"
trap 'rm -rf "$src"' EXIT
for dir in "${sources[@]}"; do
  cp -r "$dir"/. "$src"/
done

rm -rf "$out"
mkdir -p "$out"
out="$(cd "$out" && pwd)"

# PLANTUML may hold a full command (e.g. "java -jar plantuml.jar"); it defaults to the plantuml binary.
read -r -a plantuml <<< "${PLANTUML:-plantuml}"
"${plantuml[@]}" -tsvg -o "$out" "$src"/*.puml
asciidoctor -o "$out/jmolecules-catalog.html" "$src/jmolecules-catalog.adoc"

figure() {
  local file="$1"
  local caption="$2"
  if [[ -f "$out/$file" ]]; then
    printf '<figure><img src="%s" alt="%s"><figcaption>%s</figcaption></figure>\n' "$file" "$caption" "$caption"
  fi
}

{
  cat <<'HTML'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>TrainFyre architecture</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 70rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; }
  figure { margin: 1rem 0; overflow-x: auto; background: #fff; border: 1px solid #ddd; padding: 1rem; }
  figcaption { color: #555; font-size: .9rem; }
  nav a { margin-right: 1rem; }
</style>
</head>
<body>
<h1>TrainFyre architecture</h1>
HTML
  printf '<p>Generated from the source code of commit <code>%s</code>. It is rebuilt on every merge to main.</p>\n' \
    "${GITHUB_SHA:-local}"
  echo '<p><a href="jmolecules-catalog.html">jMolecules catalog (aggregates, entities, ports, adapters, commands)</a></p>'

  echo '<h2>Modules</h2>'
  figure modules-dependencies.svg "Module dependencies"
  figure components.svg "Spring Modulith components"

  for file in "$out"/hexagonal-*.svg; do
    [[ -e "$file" ]] || continue
    module="${file##*/hexagonal-}"
    module="${module%.svg}"
    echo "<h2>Module: ${module}</h2>"
    figure "hexagonal-${module}.svg" "Hexagonal view of ${module}"
    figure "domain-${module}.svg" "Domain model of ${module}"
    figure "module-${module}.svg" "Spring Modulith view of ${module}"
  done
  echo '</body></html>'
} > "$out/index.html"
